		Tool("attach_endpoint", "Attach to a Mono/Unity soft-debugger endpoint by address and port. Use this when the target was launched with --debugger-agent=transport=dt_socket,server=y,address=HOST:PORT: such a target emits no discovery beacon, so list_programs can never see it and attach cannot reach it. Returns state \"faulted\" with fault_message when the connection fails. A server=y agent accepts EXACTLY ONE connection per launch, so never TCP-probe the port to check whether the target is up: the probe consumes the single connection permanently, and this tool then faults with a connection error that reads like a target-side problem when the target is fine. Connect only with this tool, once. A clean detach makes the agent listen again; anything else means relaunching the target.", new { address=new { type="string", description="Default 127.0.0.1." }, port=new { type="integer", minimum=1, maximum=65535 }, engine=new { type="string", @enum=new[]{"unity","mono"}, description="Default unity. Must match the target's runtime." }, process_is_suspended=new { type="boolean", description="True when the agent was given suspend=y, ie. the target is parked waiting for a debugger." }, connection_timeout_ms=new { type="integer", description="Socket retry window. dnSpy's default is 10000; capped at 300000." } }, new[]{"port"}),
		Tool("launch", "Launch a target through dnSpy's debugger engine. Unlike attach, dnSpy owns the process, so terminate and restart have deterministic semantics, and the target's stdout/stderr can be captured — get_output carries them. When break_at is create_process or entry_point, the reply waits for that initial stop and its returned state/versions describe the stopped process. This call creates the process before its wait completes, so its side effect outlives a cancelled call: if it is interrupted (\"Tool execution was interrupted\"), assume the process EXISTS and do not treat that as failure. Retrying is safe — a repeat launch of the same image adopts the live session it already started instead of creating a second debuggee, and returns that session — but list_sessions shows it too, under a program_id of \"launch:<engine>:<path>\".", new { filename=new { type="string" }, engine=new { type="string", @enum=new[]{"cordebug","unity"}, description="Default cordebug." }, command_line=new { type="string" }, working_directory=new { type="string" }, break_at=new { type="string", @enum=new[]{"none","create_process","entry_point"} }, redirect_output=new { type="boolean", description="Default true: capture the target's stdout/stderr and publish them to get_output and wait_for_output. False gives the target its own console, whose output nothing can read back." }, adopt_existing=new { type="boolean", description="Default true: when a live launch session already owns this image, return it instead of starting a second process. This is what makes an interrupted launch safe to retry. Pass false only to run a second copy of the same program deliberately." }, environment=new { type="object", additionalProperties=new { type="string" } }, connection_timeout_ms=new { type="integer", minimum=1, maximum=300000 } }, new[]{"filename"}),
		Tool("get_session_state", "Get current debugger session state. You rarely need this before a mutation: every attach, launch, wait and guarded call returns the same counters in a `versions` object (lifecycle_version, execution_version, breakpoints_version, stop_id, last_event_id), read after that call applied. Take the next call's `expected_*` guards from there and call this only to resynchronize after an error or after something outside this client moved the target. Guards and cursors are different kinds of number — guards are versions, cursors are event ids, and one is never accepted for the other. `versions.last_event_id` is the newest event AT RESPONSE TIME, so it is a correct cursor for reading history with get_events, and the WRONG one to wait from for an event the same call is about to cause: a breakpoint on a hot path can be hit before a resume even returns, and waiting from a cursor that already includes that stop waits for the next one. To wait for a stop, use a cursor captured BEFORE the resume — set_breakpoint and set_il_breakpoint return exactly that as `cursor_event_id`.", new { session_id=new { type="string" } }, new[]{"session_id"}),
		Tool("list_sessions", "List active debugger sessions. Use this to recover a session_id.", new {}),
		Tool("get_session_controller", "Report whether a debugger session currently has an MCP controller. Inspection never claims it or changes target state. When owned, controller_expires_utc and controller_expires_in_seconds say when the lease lapses if that controller never calls again, so a caller that legitimately lost its transport — the MCP client replacing its stdio server gives the session a new identity and strands the old lease on a dead one — can wait a known interval instead of polling blind, then claim_session. controller_is_caller distinguishes \"someone else holds it\" from \"you already do\".", new { session_id=new { type="string" } },new[]{"session_id"}),
		Tool("claim_session", "Explicitly claim an unowned or expired debugger session after caller or Gateway recovery. Never changes target state.", new { session_id=new { type="string" } },new[]{"session_id"}),
		Tool("release_session", "Release controller ownership without resuming, detaching, terminating, or otherwise changing the target.", new { session_id=new { type="string" } },new[]{"session_id"}),
		Tool("detach", "Detach one selected process or all targets. Fails with detach_would_terminate unless allow_terminate is explicit. If the engine does not actually remove the target within 10 seconds, returns detach_timed_out and preserves the session instead of claiming success.", new { session_id=new { type="string" },process_id=new { type="integer" }, allow_terminate=new { type="boolean", description="Stop debugging even if that terminates the selected target." } }, new[]{"session_id"}),
		Tool("terminate", "Terminate one selected process or every active target explicitly.", new { session_id=new { type="string" },process_id=new { type="integer" } }, new[]{"session_id"}),
		Tool("restart", "Restart a target previously launched through dgSpy. Attached targets cannot be restarted because dgSpy does not own their launch options.", new { session_id=new { type="string" } }, new[]{"session_id"}),
		Tool("pause", "Pause one process. process_id is optional only when exactly one process is active.", new { session_id=new { type="string" }, process_id=new { type="integer" } }, new[]{"session_id"}),
		Tool("continue", "Continue one process. process_id is optional only when exactly one process is active. It does not wait for the next stop. Capture the wait cursor BEFORE calling this — set_breakpoint returns one as cursor_event_id — because a breakpoint on a hot path can be hit before this call returns, and `versions.last_event_id` in the response would then already include that stop, so waiting from it waits for the one after. To resume as far as a known place instead, run_to_method and run_to_location do the breakpoint/continue/wait/cleanup round in one call.", new { session_id=new { type="string" }, process_id=new { type="integer" } }, new[]{"session_id"}),
		Tool("set_il_breakpoint", "Set an exact module/token/IL-offset breakpoint and report whether the engine actually bound it. Check `bound`: false with severity \"error\" will never be hit, false with no error is pending a module load. On Mono/Unity a breakpoint can only sit on a sequence point; many offsets qualify but a frame's own il_offset often does not. By default, when the engine refuses the requested offset, dgSpy snaps to the first legal sequence point at or after it; only when no later point exists does it use the method's final preceding sequence point. `snapped`, `requested_il_offset`, and `il_offset` report exactly what happened. Pass snap_to_sequence_point=false to keep the refusal instead. Pass the returned `cursor_event_id` to wait_for_stop as after_event_id: a cursor read after this call has already missed the first hit on a hot method. The breakpoint starts unconditional — attach a condition, hit count or trace message by passing the returned breakpoint_id to update_breakpoint. Use get_il to see which offsets are sequence points before choosing one.", new { session_id=new { type="string" }, module=ModuleNameSchema(), method_token=new { type="integer" }, il_offset=new { type="integer" }, snap_to_sequence_point=new { type="boolean", description="Default true. On refusal, use the first legal sequence point at or after the requested offset; when none exists, use the method's final preceding sequence point." } }, new[]{"session_id","module","method_token","il_offset"}),
		Tool("list_breakpoints", "List all dnSpy breakpoints with their binding state. Breakpoints are global and outlive a session. engine_hit_count reports times the engine reached each breakpoint this session, counted before conditions run — a false-but-working condition still ticks it, distinguishing 'condition not yet true' from 'never reached'.", new {}),
		Tool("remove_breakpoint", "Remove one breakpoint by the exact id returned by set_il_breakpoint or list_breakpoints. Unlike clear_breakpoints, this leaves every other dnSpy and UI breakpoint untouched.", new { breakpoint_id=new { type="integer" } }, new[]{"breakpoint_id"}),
		Tool("clear_breakpoints", "Remove every dnSpy breakpoint, including any set by hand in the dnSpy UI. Breakpoints outlive a detach and rebind on the next attach, so clear them before reattaching if a fresh session should not stop on old ones. To drop only your own, remove_breakpoint takes one id and leaves the rest alone; to be able to put a human's back, export_breakpoints first and import_breakpoints after.", new {}),
		Tool("wait_for_stop", "Wait without polling for stops after an event cursor. Concurrent waiters do not consume events. THE CURSOR IS YOURS TO TRACK: because reads are non-destructive the server keeps no per-caller position, so every response carries last_event_id and you pass it as the next call's after_event_id. Omitting after_event_id means \"from the start of the session\", NOT \"only what is new\": a bare call replays every retained stop, so a poll loop that never advances it re-processes stops it already handled. That default is deliberate — the opposite one would silently drop a stop that landed between two calls, and a duplicate is recoverable where a lost stop is not. Seed the first cursor from set_il_breakpoint's cursor_event_id or attach's last_event_id rather than reading one afterwards. A truncated result supplies oldest_available_cursor so the caller can recover. A cursor beyond the newest event is rejected with cursor_ahead_of_stream instead of waiting forever — cursors come from cursor_event_id, event_id, or last_event_id, never from a version counter.", new { session_id=new { type="string" }, after_event_id=new { type="integer", description="Exclusive cursor: return only events with a higher id. Pass the previous response's last_event_id, or set_il_breakpoint's cursor_event_id. Default 0 replays the whole retained session." }, timeout_ms=new { type="integer", minimum=1, maximum=10000, description="Default 5000. The extension clamps to 10000; poll again with the returned cursor for longer waits." } }, new[]{"session_id"}),
		Tool("wait_for_event", "Wait without polling for any requested event kinds after a cursor. Returns immediately when a matching buffered event already exists; concurrent waiters are non-destructive. The cursor is caller-supplied on exactly the terms described on wait_for_stop: advance after_event_id with each response's last_event_id, and note that omitting it replays the session's retained history rather than returning only new events. A cursor beyond the newest event is rejected with cursor_ahead_of_stream instead of waiting forever.", new { session_id=new { type="string" }, after_event_id=new { type="integer", description="Exclusive cursor: return only events with a higher id. Pass the previous response's last_event_id, or set_il_breakpoint's cursor_event_id. Default 0 replays the whole retained session." }, kinds=new { type="array", items=new { type="string", @enum=EventKinds.All }, description="Optional normalized event-kind filter. An unrecognized kind is rejected with invalid_argument rather than silently matching nothing." }, timeout_ms=new { type="integer", minimum=1, maximum=10000, description="Default 5000. The extension clamps to 10000." } }, new[]{"session_id"}),
		Tool("get_events", "Read the STRUCTURED stream: normalized lifecycle and debugger events, without consuming them. Nothing the target printed appears here — console text is get_output. Optional kinds filter the bounded per-session stream; truncated reports when the requested cursor is older than retained history, and a cursor beyond the newest event is rejected with cursor_ahead_of_stream rather than returning a clean empty result. Shares one bounded buffer and one caller-supplied cursor with wait_for_stop and wait_for_event: advance after_event_id with each response's last_event_id, since omitting it returns the retained history rather than only what is new.", new { session_id=new { type="string" }, after_event_id=new { type="integer", description="Exclusive cursor: return only events with a higher id. Pass the previous response's last_event_id. Default 0 returns the whole retained session." }, kinds=new { type="array", items=new { type="string", @enum=EventKinds.All }, description="Optional normalized event-kind filter. An unrecognized kind is rejected with invalid_argument rather than silently matching nothing." } }, new[]{"session_id"}),
		Tool("get_stop_reason", "Read the latest normalized stop, or an exact retained stop event by event_id, including process, thread, breakpoint, exception, and location details when supplied by the debugger. stop_reason is one of: breakpoint, exception, step, entry_point, program_break, pause, unknown.", new { session_id=new { type="string" }, event_id=new { type="integer" } }, new[]{"session_id"}),
		Tool("list_threads", "List paused target threads with stable thread_id values. It does not eagerly fetch every stack because Unity threads can exit during frame retrieval; select a returned thread_id with get_callstack or get_frame. Do not try to predict func-eval viability from `states`: CorDebug publishes UnsafePoint there and Mono publishes no equivalent at all, so a rule learned on one engine is wrong on the other. Pass include_evaluability instead. A blocked result carries recovery at the point of decision: use the composed run_to_method or run_to_location workflow rather than manually assembling breakpoint, continue, wait, and cleanup. Those workflows wait for reachable code; they do not make an otherwise unreachable method execute. If arrival needs an external stimulus, issue the run-to call first and drive the stimulus while it waits.", new { session_id=new { type="string" }, include_evaluability=new { type="boolean", description="Default false. True probes each thread and adds can_evaluate, evaluate_blocked_reason (no_frames, native_frame, or unsafe_point), and recovery when blocked. Follow that recovery directly; it names the composed run-to workflow. Costs one bounded stack walk per thread; on Unity that is the call a disappearing thread can stall, which is why it is opt-in." } }, new[]{"session_id"}),
		Tool("get_callstack", "Get a paused call stack and primitive locals. Pass thread_id for deterministic caller-selected inspection; omitting it preserves the managed-frame probe fallback. Expression compilation uses the selected frame's module context: choose the nearest managed frame whose module/module_name is the target assembly, then pass its thread_id and frame_index to evaluation tools. A fully qualified target type still cannot resolve from an unrelated module such as a Thread.Sleep frame. A frame with raw_locals true reports its locals as the runtime's raw slots V_0, V_1, ... because the engine recovered no source-level names for it; see get_frame.", new { session_id=new { type="string" }, thread_id=new { type="string" }, max_frames=new { type="integer", minimum=1, maximum=100 } }, new[]{"session_id"}),
		Tool("get_frame", "Inspect one paused frame by caller-selected thread_id and zero-based frame_index. `locals` holds primitive scalars only; pass include to also get objects and `this` in `values`, which is one round trip against one evaluation context. Values carry `address`/`address_length` when the runtime has one — see read_memory. When raw_locals is true the engine could not recover source-level variable names for this frame, so the locals are its raw slots named V_0, V_1, ...; those are ordinary expressions and can be evaluated, expanded and assigned to like any name.", new { session_id=new { type="string" }, thread_id=new { type="string" }, frame_index=new { type="integer", minimum=0, maximum=99 }, include=new { type="array", items=new { type="string", @enum=new[]{"locals","this"} }, description="locals covers arguments too — dnSpy does not separate them. Unknown values are rejected rather than ignored." }, allow_func_eval=new { type="boolean", description="Default false." } }, new[]{"session_id","thread_id","frame_index"}),
		Tool("update_breakpoint", "THIS IS WHERE CONDITIONAL BREAKPOINTS LIVE. Change an existing breakpoint's enabled state, condition, hit count, or trace message, using a breakpoint_id from set_breakpoint, set_il_breakpoint or list_breakpoints. A condition (`i == 3`, `name == \"x\"`) or a hit count is how you stop at one specific loop iteration; stepping to it, or computing which iteration it would be, is neither necessary nor reliable. Conditions and hit counts are evaluated by the engine inside the target, so a condition that cannot be evaluated fails at hit time rather than here — list_breakpoints reports engine_hit_count, counted before the condition runs, which separates \"condition never true\" from \"never reached\". Pass an empty string for condition or trace_message to clear it; omit a field to leave it unchanged.", new { breakpoint_id=new { type="integer" }, enabled=new { type="boolean" }, condition=new { type="string", description="Expression in the target's language. Empty string clears the condition." }, condition_kind=new { type="string", @enum=BreakpointConditionKinds.All, description="Default is_true. when_changed stops when the value differs from the previous hit." }, hit_count=new { type="integer", minimum=1 }, hit_count_kind=new { type="string", @enum=HitCountKinds.All, description="Default equals (stop on exactly the nth hit)." }, trace_message=new { type="string", description="Print instead of (or as well as) stopping. Empty string clears. The message goes to dnSpy's Output window only: it is NOT on the get_output stream and produces no event, so an MCP caller cannot read it. Use a condition and a real stop instead unless a human is watching the window." }, trace_continue=new { type="boolean", description="Default true: print and keep running, which produces NO stopped event. Pass false to print and stop." } }, new[]{"breakpoint_id"}),
		Tool("set_exception_breakpoint", "Stop when an exception is thrown. Pass a fully qualified type name, or omit name to set the category's default that governs every exception it does not name. Like code breakpoints these are dnSpy-global and outlive a session. Exception breakpoints and exception policies are ONE thing: this writes the same entry set_exception_policy writes (that tool additionally takes module conditions); list with either list tool and remove with remove_exception_policy.", new { category=new { type="string", description="Default DotNet." }, name=new { type="string", description="Fully qualified type, eg. System.InvalidOperationException. Omit for the category default." }, stop_first_chance=new { type="boolean", description="Stop when thrown, before the target gets to handle it." }, stop_second_chance=new { type="boolean", description="Stop when it goes unhandled." } }),
		Tool("list_exception_breakpoints", "List exceptions configured to break on throw. By default this reports first-chance entries only, which is the set someone deliberately configured: dnSpy stops on SECOND chance for essentially every .NET exception it knows, so including those returns thousands of identical stock entries that say nothing about this session. Bounded, with total and truncated. Same underlying entries as list_exception_policies; that tool is the raw view with module conditions, and takes the same category and name filters.", new { category=ExceptionCategoryFilterSchema(), name=ExceptionNameFilterSchema(), include_second_chance=new { type="boolean", description="Default false. True adds dnSpy's stock second-chance defaults — expect thousands of entries." }, max_results=new { type="integer", minimum=1, maximum=1000, description="Default 200." } }),
		Tool("step_into", "Step into the call at the current instruction. The stop arrives on the event stream like any other, with stop_reason \"step\": pass the returned cursor_event_id to wait_for_stop. The result's status says what happened: \"completed\", \"step_error\", or \"in_flight\" with a hint — in_flight means the target is running again and a step across interop, optimized, or interpreted code may never land. See step_and_inspect to combine a step with evaluation in one call.", new { session_id=new { type="string" }, thread_id=new { type="string", description="Defaults to the thread that carried the stop. Stepping the wrong thread resumes the target and stops somewhere unrelated, so pass this explicitly when several threads are interesting." } }, new[]{"session_id"}),
		Tool("step_over", "Step over the call at the current instruction. See step_into for how completion is reported. Stepping repeatedly and reading state each time is what step_and_inspect does in one call; to reach a distant point, prefer run_to_method or a conditional breakpoint (see set_breakpoint) over a step loop.", new { session_id=new { type="string" }, thread_id=new { type="string" } }, new[]{"session_id"}),
		Tool("step_out", "Run to the caller of the current frame. See step_into for how completion is reported, and step_and_inspect to step and inspect in one call. An active breakpoint in the method being left hits first: the step reports completed:false and the next stop is that breakpoint, not the caller. Remove it first when the point is to reach the frame above.", new { session_id=new { type="string" }, thread_id=new { type="string" } }, new[]{"session_id"}),
		Tool("evaluate", "Evaluate an expression against a paused frame. Returns the raw scalar and dnSpy's formatted display text as separate fields, so numbers stay comparable without parsing display text. has_raw_value distinguishes a value of null from a value that is unavailable or optimized away. Running target code is guarded by TWO independent gates, both off by default and NOT interchangeable: allow_func_eval permits executing target code at all, allow_side_effects permits an expression dnSpy classifies as side-effecting. A property getter such as DateTime.Now.Ticks trips only the first, so allow_func_eval alone runs it — and it can deadlock a target holding a lock or mutate what you were inspecting, which is why it is off. An explicit method call such as Telemetry.ComputeReading(5) trips BOTH, and side effects are checked first, so passing allow_func_eval alone leaves the error \"This expression causes side effects and will not be evaluated\" completely unchanged, which reads like the flag was ignored and is not. Pass both for a method call, or use invoke_method, which sets both and audits the call. One exception explains conflicting reports of this tool: dnSpy's `ac` (\"always calculate\") format specifier, appended as `Some.Method(1), ac`, opens the side-effects gate on its own, so that shape DOES succeed with allow_func_eval alone; it is dnSpy syntax rather than a dgSpy argument and bypasses the opt-in, so prefer allow_side_effects. Every refusal carries `recovery` naming the gate that blocked it; never fall back to computing a method's result by hand. For an object, get_members expands it a level rather than guessing member names; get_autos returns what the current statement touches without naming anything; add_watch re-evaluates the same expression at every later stop, which a value read here cannot survive. A value carries `address`/`address_length` when the runtime has one, which is the supported way to reach a managed object with read_memory and write_memory. Expressions compile in the selected frame's module context. After CS0103, use get_callstack and select the nearest managed frame in the target module with thread_id and frame_index; even a fully qualified target type cannot resolve from an unrelated module. The error also names variables this frame can address, including V_n slots when it reports no source-level names.", new { session_id=new { type="string" }, expression=new { type="string" }, thread_id=new { type="string", description="Defaults to the thread that carried the stop." }, frame_index=new { type="integer", minimum=0, description="Default 0." }, allow_func_eval=new { type="boolean", description="Default false. True permits running target code, eg. property getters and ToString. It does NOT imply allow_side_effects and cannot substitute for it." }, allow_side_effects=new { type="boolean", description="Default false. True permits an expression dnSpy classifies as side-effecting, which every explicit method call is. Required in addition to allow_func_eval to call a method, including a pure one — dnSpy classifies by expression shape, not by what the method actually does." } }, new[]{"session_id","expression"}),
		Tool("invoke_method", "SIDE EFFECTING and audited. Evaluate a complete method-call expression in the paused target. This injects a nested func-eval; it is not natural-control-flow arrival at the method, and breakpoints inside the invoked call are not serviced. Never use it to satisfy a request to reach or arrive at code: use run_to_method or run_to_location, whose timed_out result proves whether natural execution arrived. Func-eval and side effects are always enabled by this tool boundary and cannot be downgraded or enabled accidentally through evaluate. On failure read compiler_error: true means the expression never compiled and nothing ran, so fix the expression; false means it compiled and the engine refused to execute it here, so the same call can succeed against another thread or another stop. A func-eval needs a thread the engine will let it start on — call list_threads with include_evaluability=true and pass a thread_id whose can_evaluate is true. If none qualifies, prepare or drive the target state, then use run_to_method or run_to_location to reach a managed frame that can evaluate. For CS0103, use get_callstack and select the nearest frame in the target module; qualification alone does not make a type visible from an unrelated frame module.", EvalMutationSchema(), new[]{"session_id","expression"}),
		Tool("create_object", "SIDE EFFECTING and audited. Evaluate a complete object-construction expression in the paused target. Func-eval and side effects are always enabled. compiler_error and thread selection work exactly as described on invoke_method.", EvalMutationSchema(), new[]{"session_id","expression"}),
		Tool("read_memory", "Read up to 65536 bytes from the selected debug process. Returns base64 and the runtime capability used. To get the address of a managed object, read the `address` and `address_length` fields that evaluate, get_members and get_frame report for every value that has one — for a string or an array that is the element data, so it is what you want for the bytes. Do NOT reach for GCHandle.Alloc(x, Pinned).AddrOfPinnedObject() through invoke_method: it costs a func-eval and leaks a pinned handle into the debuggee for the rest of its life, pinning the heap you were inspecting. An address is valid only for the current stop; a moving GC relocates objects on every resume, so re-read it after each stop rather than caching it across a continue.", new { session_id=new { type="string" }, process_id=new { type="integer" }, address=new { type="integer", minimum=0 }, length=new { type="integer", minimum=1, maximum=65536 } }, new[]{"session_id","address","length"}),
		Tool("write_memory", "SIDE EFFECTING and audited. Write up to 65536 base64-encoded bytes to the selected debug process. Get a managed object's address from the `address`/`address_length` fields on evaluate, get_members and get_frame values, as described on read_memory. The address is checked against nothing here: it is valid only for the stop it was read at, and writing through one cached across a continue corrupts whatever the GC moved into that space. Re-read it after every stop, and stay inside address_length.", new { session_id=new { type="string" }, process_id=new { type="integer" }, address=new { type="integer", minimum=0 }, data_base64=new { type="string" } }, new[]{"session_id","address","data_base64"}),
		Tool("get_disassembly", "Return managed IL or the selected frame's JIT native code blocks. Unsupported native bodies return a structured capability failure.", new { session_id=new { type="string" }, mode=new { type="string", @enum=new[]{"managed","native"} }, module=new { type="string", description="Required with managed mode." }, method_token=new { type="integer", description="Required with managed mode." }, thread_id=new { type="string" }, frame_index=new { type="integer", minimum=0 } }, new[]{"session_id"}),
		Tool("get_registers", "Return a stopped x64 thread's integer and control registers for CorDebug or Mono soft-debugger protocol 2.3+. Each row includes name, unsigned numeric value, fixed-width hexadecimal text, and bit width. The selected thread must be paused. READ frame_relation BEFORE THE NUMBERS. This is the OS thread's context, which at a managed stop is usually NOT the managed frame's: the runtime suspends the thread inside its own stop machinery, so rip sits in ntdll, rcx holds a wait handle rather than `this`, and rbp is a sentinel rather than a frame base. Those are true readings of the machine and wrong answers about the frame, and nothing in the values themselves tells them apart. frame_relation is \"matched\" (rip is inside this frame's JIT-compiled body, so the context does describe it), \"unrelated\" (it does not — the usual result at a breakpoint, and always so for any frame_index above 0, since rip belongs to the leaf), or \"unknown\" (the frame's native range could not be read). `note` says why. When it is not \"matched\", do not derive frame state from these registers: use get_frame, evaluate, or a value's `address` instead.", new { session_id=new { type="string" }, thread_id=new { type="string" },frame_index=new { type="integer",minimum=0 } }, new[]{"session_id"}),
		Tool("set_instruction_pointer", "SIDE EFFECTING and audited. Move the selected thread within its current managed method after engine CanSetIP validation.", new { session_id=new { type="string" }, thread_id=new { type="string" }, frame_index=new { type="integer", minimum=0 }, module=ModuleNameSchema(), method_token=new { type="integer" }, il_offset=new { type="integer", minimum=0 } }, new[]{"session_id","module","method_token","il_offset"}),
		Tool("get_members", "Expand one object one level, paged. Pass a returned member's `expression` back here to go deeper: depth is deliberately the caller's to control, because recursing server-side is unbounded on a cyclic object graph. A member whose `expression` is empty cannot be addressed at all: either a compiler-generated member (auto-property backing field, async or iterator state machine field, lambda display class) whose name is not spellable in any language, or a grouping row such as `Static members` that carries a type name rather than an expression. Its name, type and value are still accurate; do not retry it. Static members stay reachable by naming them directly, eg. `Some.Type.SomeStaticField`, but expression compilation still uses the selected frame's module; after CS0103 use get_callstack and select the nearest frame in the target module. Reports total and truncated. Members carry `address`/`address_length` when the runtime has one — see read_memory.", new { session_id=new { type="string" }, expression=new { type="string" }, thread_id=new { type="string" }, frame_index=new { type="integer", minimum=0 }, offset=new { type="integer", minimum=0, description="Default 0." }, count=new { type="integer", minimum=1, maximum=200, description="Default 50." }, allow_func_eval=new { type="boolean", description="Default false." } }, new[]{"session_id","expression"}),
		Tool("set_value", "Assign to a local, parameter, field or property in the paused target. Always side-effecting: the assignment executes in the target. When this assignment prepares a flag, input, or counter that makes the target call the next method, keep the target paused for the assignment and then use run_to_method or run_to_location; do not manually assemble breakpoint, continue, wait, and cleanup. compiler_error=true means the expression did not compile and nothing ran; an error without it means the target may already have been touched. Executing in the target is not the same as needing a func-eval, and the difference decides what is still possible against an idle process. Storing a value that already exists over there is a direct write and succeeds even with every thread at an unsafe point; producing a value the engine must first create — a string literal, a boxed value, a new object — is a func-eval and is refused at an unsafe point like any other. The cost of the value is what matters, not whether the target is a primitive: assigning null to a reference is as free as assigning an int, while assigning a string literal to that same reference is refused. When it is refused, see invoke_method for how to reach a thread that can evaluate; note also that the unsafe-point thread's evaluable frame is often not frame 0, so pass frame_index for the frame whose locals you actually want. A CS0103 \"does not exist in the current context\" error names the variables this frame can actually address: when the engine recovers no source-level names for a method its locals are reachable only as the raw slots V_0, V_1, ..., which assign like any other name.", new { session_id=new { type="string" }, expression=new { type="string", description="What to assign to, eg. input or this.counter." }, value=new { type="string", description="Expression producing the new value, eg. 42." }, thread_id=new { type="string" }, frame_index=new { type="integer", minimum=0 }, allow_func_eval=new { type="boolean", description="Default false." } }, new[]{"session_id","expression","value"}),
		Tool("get_exception", "Get the exception that stopped the target, from dnSpy's own exceptions provider rather than a typed expression. An empty array is a normal answer: most stops are not exception stops.", new { session_id=new { type="string" }, thread_id=new { type="string" }, frame_index=new { type="integer", minimum=0 }, allow_func_eval=new { type="boolean" } }, new[]{"session_id"}),
		Tool("add_watch", "Store an expression to re-evaluate later. Watches are expressions, not value handles: a handle goes stale on the next resume, an expression survives it. Adding the same expression twice returns the existing watch_id.", new { session_id=new { type="string" }, expression=new { type="string" } }, new[]{"session_id","expression"}),
		Tool("list_watches", "Evaluate every stored watch against a paused frame in one pass. A watch whose expression fails reports its own error instead of failing the call, so one bad expression cannot hide the rest.", new { session_id=new { type="string" }, thread_id=new { type="string" }, frame_index=new { type="integer", minimum=0 }, allow_func_eval=new { type="boolean" } }, new[]{"session_id"}),
		Tool("remove_watch", "Remove one stored watch by id.", new { session_id=new { type="string" }, watch_id=new { type="integer" } }, new[]{"session_id","watch_id"}),
		Tool("list_modules", "List loaded modules for every runtime in the session, filtered and paged. Pass name_pattern rather than fetching everything: a Unity player loads 170 modules and the unfiltered answer runs to tens of thousands of characters. Reports total and truncated. can_set_breakpoint reflects whether the engine publishes a stable ModuleId; metadata-backed in-memory and dynamic modules are supported even without a file path.", new { session_id=new { type="string" }, name_pattern=ModuleNameSchema("Case-insensitive filter on module name or path."), offset=new { type="integer", minimum=0 }, count=new { type="integer", minimum=1, maximum=500, description="Default 100." } }, new[]{"session_id"}),
		Tool("list_documents", "List loaded modules with their metadata state: assembly full name, type count, and whether dnSpy could load metadata at all, filtered and paged like list_modules. Each row loads metadata, so name_pattern saves work and not only output. A module whose metadata fails to load is reported with has_metadata=false rather than omitted, because a silently missing module makes a type that exists look like it does not.", new { session_id=new { type="string" }, name_pattern=ModuleNameSchema("Case-insensitive filter on module name or path."), offset=new { type="integer", minimum=0 }, count=new { type="integer", minimum=1, maximum=500, description="Default 100." } }, new[]{"session_id"}),
		Tool("list_types", "Drill-in tool: use it when you already know the module and want to enumerate it. To find a type by name, use `search` — it resolves qualified names and returns the module. List types in a loaded module, filtered and paged. Each result carries the metadata token, so a breakpoint can be set from it without parsing display text.", new { session_id=new { type="string" }, module=new { type="string", description="Full path, filename, or module name from list_modules." }, name_pattern=new { type="string", description="Case-insensitive substring match on the full type name." }, offset=new { type="integer", minimum=0 }, count=new { type="integer", minimum=1, maximum=500, description="Default 100." } }, new[]{"session_id","module"}),
		Tool("list_members", "Drill-in tool for a type `search` already identified. `type` must name a TYPE, not a path: `A.B` where B is a field on A is not a type, and the error says so rather than implying the member does not exist. List methods, fields, properties and events of a type, with metadata tokens. An ambiguous type name is reported with the candidates rather than resolved by guessing.", new { session_id=new { type="string" }, module=ModuleNameSchema(), type=new { type="string", description="Full type name, or a unique short name." }, name_pattern=new { type="string" }, offset=new { type="integer", minimum=0 }, count=new { type="integer", minimum=1, maximum=500, description="Default 200." } }, new[]{"session_id","module","type"}),
		Tool("search", "START HERE when you have a name and need a symbol. dnSpy's Search window as a tool: it matches the same candidate strings the GUI does, so a qualified path works — pattern 'GameState.ChatSystem' finds the ChatSystem field on type GameState, which search_symbols cannot. Space-separated terms are AND-ed, /slashes/ make it a regular expression, and kinds covers every entry of the GUI's Search For dropdown including property, event, parameter, local and literal. Every returned identifier round-trips: full_name is accepted back here as pattern, declaring_type is accepted by list_members and get_csharp, and module plus token is accepted by get_il, find_references and set_il_breakpoint. Nothing needs parsing. Bounded by max_scan over inspected symbols, not by the clock; scan_truncated=true means work stopped early and next_scan_offset resumes exactly where it left off. Pass module on Unity, where a whole-process scan means hundreds of thousands of framework symbols.", new { session_id=new { type="string", description="Required unless scope is documents." }, pattern=new { type="string", description="Terms are AND-ed unless match_any_word. /text/ is a regular expression. In literal mode, \"quoted\" is a string and 0x1F or 3.5 is a number." }, kinds=new { type="array", items=new { type="string", @enum=new[]{"assembly","module","namespace","type","field","method","property","event","parameter","local","parameter_or_local","assembly_ref","module_ref","resource","generic_type","non_generic_type","enum","interface","class","struct","delegate","member","any","literal"} }, description="Default [type, member]. member = method+field+property+event. literal searches constant values, ldc/ldstr operands and resource names instead of names, and cannot be combined with name kinds. Custom attribute arguments are not searched." }, scope=new { type="string", @enum=new[]{"session","documents","all"}, description="session (default) searches the debug session's loaded modules, the same set every other decompiler tool uses. documents searches dnSpy's Assembly Explorer and needs no attached process. all searches both. Every hit carries in_session, which is false when the session tools will answer module_not_found for it." }, module=new { type="string", description="Substring filter on module name or path." }, count=new { type="integer", minimum=1, maximum=500, description="Default 100." }, max_scan=new { type="integer", minimum=1, maximum=2000000, description="Hard work bound in inspected symbols; default 200000." }, scan_offset=new { type="integer", minimum=0, description="Resume cursor: pass a previous response's next_scan_offset." }, case_sensitive=new { type="boolean", description="Default false." }, whole_word=new { type="boolean", description="Default false." }, match_any_word=new { type="boolean", description="Default false; true ORs the terms instead of ANDing them." }, compiler_generated=new { type="boolean", description="Default true. Keep it true to find auto-property backing fields and state-machine members." } }, new[]{"pattern"}),
		Tool("search_symbols", "Prefer `search`. This is the older, narrower matcher: it compares the simple name only, so it cannot find 'Type.Member' even though that is the shape it returns as full_name, and it covers only type, method and field — no properties, events, parameters, locals or literals. Kept for compatibility. Find types and members by name across the session's loaded modules; bounded, reports total and truncated. Pass module to avoid searching every loaded assembly, which on Unity means thousands of framework types.", new { session_id=new { type="string" }, pattern=new { type="string", description="Case-insensitive substring, matched against the simple name only." }, kinds=new { type="array", items=new { type="string", @enum=new[]{"type","method","field"} }, description="Default [type, method]." }, module=new { type="string", description="Substring filter on module name or path." }, count=new { type="integer", minimum=1, maximum=500, description="Default 100." } }, new[]{"session_id","pattern"}),
		Tool("get_il", "Disassemble a method to IL with offsets and operands. is_sequence_point marks the offsets Mono will accept a breakpoint at — it rejects every other one with NO_SEQ_POINT_AT_IL_OFFSET, which dnSpy turns into a silently unbound breakpoint. has_sequence_points=false means no PDB was available, NOT that there are no legal offsets. Identify the method by method_token, or by type plus method.", new { session_id=new { type="string" }, module=ModuleNameSchema(), method_token=new { type="integer" }, type=new { type="string" }, method=new { type="string" }, signature=new { type="string", description="Full name of the intended overload, when type+method is ambiguous." } }, new[]{"session_id","module"}),
        Tool("get_csharp", "Decompile a method, or a whole type with whole_type=true. Identify a method by method_token or by type plus method.", new { session_id=new { type="string" }, module=ModuleNameSchema(), method_token=new { type="integer" }, type=new { type="string" }, method=new { type="string" }, signature=new { type="string" }, whole_type=new { type="boolean", description="Default false. True decompiles the entire type, which can be very large." } }, new[]{"session_id","module"}),
		Tool("set_breakpoint", "Set a breakpoint by type and method name instead of a metadata token. Resolves the name, then takes exactly the same path as set_il_breakpoint, so binding state, Mono sequence-point snapping and cursor_event_id behave identically — read that tool's description. Overloads are reported as ambiguous with their full names rather than resolved by guessing. CONDITIONAL BREAKPOINTS: this tool sets an unconditional one; pass the returned breakpoint_id to update_breakpoint to attach a condition (`i == 3`), a hit count (stop on the nth hit), or a trace message that prints without stopping. To stop at one specific loop iteration, do that rather than stepping to it or computing the value by hand.", new { session_id=new { type="string" }, module=ModuleNameSchema(), type=new { type="string" }, method=new { type="string" }, signature=new { type="string", description="Full name of the intended overload." }, il_offset=new { type="integer", description="Default 0 (method entry)." }, snap_to_sequence_point=new { type="boolean", description="Default true." } }, new[]{"session_id","module","type","method"}),
		Tool("search_text", "Heavier than `search`, and the last resort: it decompiles method bodies one at a time. For string and number constants use `search` with kinds:[\"literal\"], which reads IL and costs a fraction of this. Use this only when the thing you are looking for exists solely in decompiled C# — a language construct rather than a name or a constant. Search decompiled C# text in loaded modules. Output and work are bounded; scan_truncated means max_methods stopped the scan before the selected scope was exhausted, and next_scan_offset fed back as scan_offset continues exactly where it stopped. Only scan_truncated=false means the scope really was swept — an agent that took a truncated result for a finished one reported a plugin had no hotkeys when it had three. Pass module and type on Unity.", new { session_id=new { type="string" }, pattern=new { type="string" }, module=ModuleNameSchema(), type=new { type="string", description="Optional declaring-type substring." }, count=new { type="integer", minimum=1, maximum=200 }, max_methods=new { type="integer", minimum=1, maximum=1000, description="Hard work bound in methods decompiled; default 200. Deliberately small: this tool decompiles. To cover more, keep it and page with scan_offset." }, scan_offset=new { type="integer", minimum=0, description="Resume cursor: pass a previous response's next_scan_offset, with the same module and type arguments." } }, new[]{"session_id","pattern"}),
		Tool("find_references", "Drill-in tool. Takes module plus token, which is exactly what `search` returns. Find loaded methods whose IL references a target metadata member. The target is module plus token; search_module optionally limits the scan.", new { session_id=new { type="string" }, module=ModuleNameSchema(), token=new { type="integer" }, search_module=ModuleNameSchema(ModuleFilterRule), count=new { type="integer", minimum=1, maximum=500 } }, new[]{"session_id","module","token"}),
		Tool("find_implementations", "Drill-in tool. Takes module plus token or a type name, both of which `search` returns. Find directly derived types and direct interface implementers. search_module limits the loaded modules scanned and should be used on Unity.", new { session_id=new { type="string" }, module=ModuleNameSchema(), token=new { type="integer" }, type=new { type="string" }, search_module=ModuleNameSchema(ModuleFilterRule), count=new { type="integer", minimum=1, maximum=500 } }, new[]{"session_id","module"}),
		Tool("get_metadata", "Module-level facts, not a way to locate a symbol — use `search` for that. Return bounded metadata facts for a module and optionally resolve one metadata token.", new { session_id=new { type="string" }, module=ModuleNameSchema(), token=new { type="integer" } }, new[]{"session_id","module"}),
		Tool("create_object_id", "Create a runtime-scoped persistent object ID for an evaluated C# expression.", new { session_id=new { type="string" },expression=new { type="string" },process_id=new { type="integer" },runtime_id=new { type="string" },thread_id=new { type="string" },frame_index=new { type="integer",minimum=0 },allow_func_eval=new { type="boolean" } },new[]{"session_id","expression"}),
		Tool("list_object_ids", "List object IDs in one explicitly selected runtime.", new { session_id=new { type="string" },process_id=new { type="integer" },runtime_id=new { type="string" } },new[]{"session_id"}),
		Tool("evaluate_object_id", "Evaluate a persistent object ID in a paused frame.", new { session_id=new { type="string" },object_id=new { type="integer",minimum=0 },process_id=new { type="integer" },runtime_id=new { type="string" },thread_id=new { type="string" },frame_index=new { type="integer",minimum=0 },allow_func_eval=new { type="boolean" } },new[]{"session_id","object_id"}),
		Tool("release_object_id", "Release one runtime-scoped object ID.", new { session_id=new { type="string" },object_id=new { type="integer",minimum=0 },process_id=new { type="integer" },runtime_id=new { type="string" } },new[]{"session_id","object_id"}),
		Tool("get_autos", "Return up to 200 C# expressions referenced by the selected frame's current source statement. dgSpy derives the statement from dnSpy language debug info, maps its IL operands to active locals, parameters, this, and fields, then evaluates them through the normal value pipeline. Function evaluation remains off unless allow_func_eval=true.", new { session_id=new { type="string" },process_id=new { type="integer" },runtime_id=new { type="string" },thread_id=new { type="string" },frame_index=new { type="integer",minimum=0 },allow_func_eval=new { type="boolean" } },new[]{"session_id"}),
		Tool("get_output", "Read the bounded non-destructive TEXT stream after a cursor: the debugged program's text plus the host's commentary, interleaved in one ring and told apart by category. DebugOutput is a managed debugger log message (for example Debugger.Log on CorDebug) and is available for attached as well as launched targets. StandardOutput and StandardError are a launched program's redirected stdout/stderr, reassembled into whole lines. Output, ErrorUser and StepFilter are host records, including the audit line every side-effecting call writes. An attached process's console handles were never ours, so its stdout/stderr cannot be captured after the fact. To block until the next line arrives instead of polling, use wait_for_output. Structured events — breakpoint hits, steps, exceptions, process exit — are not here; they are get_events.", new { session_id=new { type="string" },after_output_id=new { type="integer",minimum=0,description="Cursor from a previous response's last_output_id. Omit to read from the oldest retained line." } },new[]{"session_id"}),
		Tool("wait_for_output", "Wait, without consuming, for new text on exactly the stream get_output returns — debug output, launched-program stdout/stderr, and host commentary. Use it to wait for something the program writes; use wait_for_stop or wait_for_event to wait for a debugger event. A trailing line written without a newline is published after a short quiet period rather than held until its next write, so a prompt still arrives.", new { session_id=new { type="string" },after_output_id=new { type="integer",minimum=0 },timeout_ms=new { type="integer",minimum=1,maximum=10000,description="Default 5000." } },new[]{"session_id"}),
		Tool("set_module_breakpoint", "Stop on module load or unload using dnSpy module filters.", ModuleBreakpointSchema(),new[]{"session_id"}),
		Tool("list_module_breakpoints", "List global dnSpy module breakpoints.", new { session_id=new { type="string" } },new[]{"session_id"}),
		Tool("update_module_breakpoint", "Update one module breakpoint; omitted filters remain unchanged.", ModuleBreakpointSchema(true),new[]{"session_id","breakpoint_id"}),
		Tool("remove_module_breakpoint", "Remove one module breakpoint.", new { session_id=new { type="string" },breakpoint_id=new { type="integer" } },new[]{"session_id","breakpoint_id"}),
		Tool("export_breakpoints", "Export code, trace, module, and exception policies as bounded canonical dgspy.breakpoints v1 JSON.", new { session_id=new { type="string" },max_exception_policies=new { type="integer",minimum=1,maximum=5000 } },new[]{"session_id"}),
		Tool("import_breakpoints", "Validate, dry-run, merge, or explicitly replace breakpoints from canonical JSON.", new { session_id=new { type="string" },document=new { type="object" },mode=new { type="string",@enum=new[]{"merge","replace"} },dry_run=new { type="boolean" } },new[]{"session_id","document"}),
		Tool("list_exception_categories", "List dnSpy exception categories.", new { session_id=new { type="string" } },new[]{"session_id"}),
		Tool("list_exception_policies", "List bounded exception definitions with flags and module conditions — the raw view of the same entries list_exception_breakpoints reports, without that tool's first-chance default filter. Pass category and name to read ONE entry, which is how a remove_exception_policy is confirmed: entries is empty and total is 0 when it is gone. Reports total and truncated.", new { session_id=new { type="string" },category=ExceptionCategoryFilterSchema(),name=ExceptionNameFilterSchema(),count=new { type="integer",minimum=1,maximum=2000,description="Default 200." } },new[]{"session_id"}),
		Tool("set_exception_policy", "Add or replace thrown/unhandled flags and module conditions for an exception. Writes the same entry set_exception_breakpoint writes; use this form when module conditions are needed.", ExceptionPolicySchema(),new[]{"session_id"}),
		Tool("remove_exception_policy", "Remove one exception policy (the same entries set_exception_breakpoint and set_exception_policy create). Returns removed=true with the entry's former flags under former_policy — those flags describe what was just deleted, not something still in effect. Confirm with list_exception_policies passing the same category and name; total 0 means it is gone. To undo every policy change at once instead, see restore_exception_defaults.", new { session_id=new { type="string" },category=new { type="string",description="Default DotNet." },name=new { type="string",description="Fully qualified type name. Omit to remove the category default entry." } },new[]{"session_id"}),
		Tool("restore_exception_defaults", "Reset dnSpy exception policies to defaults and remove user additions, including entries created by set_exception_breakpoint.", new { session_id=new { type="string" } },new[]{"session_id"}),
		Tool("get_value_export", "Serialize a supported evaluated value as bounded base64 chunks with whole-value SHA-256.", ValueExportSchema(),new[]{"session_id","expression"}),
		Tool("write_value_export", "SIDE EFFECTING and audited. Write an evaluated value below DGSPY_EXPORT_ROOT; no overwrite by default.", new { session_id=new { type="string" },expression=new { type="string" },path=new { type="string" },overwrite=new { type="boolean" },process_id=new { type="integer" },runtime_id=new { type="string" },thread_id=new { type="string" },frame_index=new { type="integer",minimum=0 } },new[]{"session_id","expression","path"}),
		Tool("analyze_symbol", "Drill-in tool for a symbol `search` already found; it takes the module and token search returns. Return bounded typed caller, callee, construction, field, override, implementation, and attribute edges. Bounded by max_scan over inspected symbols and resumable: scan_truncated=true means work stopped early, and next_scan_offset fed back as scan_offset continues exactly there, so a module bigger than one call's bound is still coverable. Before the cursor existed, the callers of a method in a 7227-method module could not be found at any setting. Pass search_module on Unity, where an unfiltered scan means every framework assembly.", new { session_id=new { type="string" },module=ModuleNameSchema(),token=new { type="integer" },search_module=ModuleNameSchema(ModuleFilterRule),count=new { type="integer",minimum=1,maximum=500 },max_scan=new { type="integer",minimum=1,maximum=2000000,description="Hard work bound in inspected symbols, types and methods alike; default 20000." },scan_offset=new { type="integer",minimum=0,description="Resume cursor: pass a previous response's next_scan_offset, with the same search_module." },max_methods=new { type="integer",minimum=1,maximum=2000000,description="The older name for max_scan, still honoured. Its old 5000 ceiling is gone; it was low enough to make large modules unreachable." } },new[]{"session_id","module","token"}),
		Tool("get_raw_module", "Read a loaded module image as a paged base64 chunk with total size and SHA-256. File-less modules are reconstructed from runtime metadata.", new { session_id=new { type="string" }, module=ModuleNameSchema(), offset=new { type="integer", minimum=0 }, count=new { type="integer", minimum=1, maximum=1048576 } }, new[]{"session_id","module"})
	};
	// One sentence about the one module-name rule, repeated on every argument that takes one, so a caller
	// never has to discover per tool whether the argument is an exact name or a substring. Half this
	// family used to be each: get_csharp(module: "Assembly-CSharp") answered module_not_found while
	// search(module: "Assembly-CSharp") searched it, and nothing in either schema said so.
	const string ModuleNameRule="Module name, filename, or full path, from search or list_modules. Case-insensitive and the file extension is optional, so \"Assembly-CSharp\" resolves \"Assembly-CSharp.dll\". A substring matches too, but an exact name always beats one, so a stem is never ambiguous against a longer neighbour. When it does not resolve, the error names the closest loaded modules.";
	const string ModuleFilterRule="Filter on module name or path, by the same rule the module argument uses: exact name, name without its extension, or substring. Case-insensitive.";
	static object ModuleNameSchema(string? description=null)=>new { type="string", description=description ?? ModuleNameRule };
	// The two exception list tools report the same entries, so they narrow a lookup the same way. Exact
	// match, not substring: the question these answer is "is THIS entry present", which a neighbour whose
	// name merely contains the one asked for would answer wrongly.
	static object ExceptionCategoryFilterSchema()=>new { type="string", description="Exact category, eg. DotNet. Omit for every category." };
	static object ExceptionNameFilterSchema()=>new { type="string", description="Exact fully qualified type name. The empty string selects the category default entry, the one set_exception_breakpoint writes when name is omitted. Omit the argument entirely for every entry." };
	static object ModuleBreakpointSchema(bool includeId=false)=>new { session_id=new { type="string" },breakpoint_id=new { type="integer" },enabled=new { type="boolean" },module_name=new { type="string" },is_dynamic=new { type="boolean" },is_in_memory=new { type="boolean" },is_loaded=new { type="boolean" },order=new { type="integer",minimum=0 },process_name=new { type="string" },app_domain_name=new { type="string" } };
	static object ExceptionPolicySchema()=>new { session_id=new { type="string" },category=new { type="string" },name=new { type="string" },stop_thrown=new { type="boolean" },stop_unhandled=new { type="boolean" },conditions=new { type="array",items=new { type="object" } } };
	static object ValueExportSchema()=>new { session_id=new { type="string" },expression=new { type="string" },process_id=new { type="integer" },runtime_id=new { type="string" },thread_id=new { type="string" },frame_index=new { type="integer",minimum=0 },offset=new { type="integer",minimum=0 },count=new { type="integer",minimum=1,maximum=1048576 } };
}
